"""Write AI-disclosure metadata (ID3) into every voice file: these voices are generated by Microsoft Azure neural text-to-speech."""
import json, os, subprocess, sys, tempfile
lines = {l['id']: l for l in json.load(open(sys.argv[1]))}
d = sys.argv[2]
for f in sorted(os.listdir(d)):
    if not f.endswith('.mp3'): continue
    l = lines[f[:-4]]
    who = f[:-4].split('_')[0].capitalize()
    note = (f"AI-generated audio (Super Intelligence): synthetic voice made with Microsoft Azure neural text-to-speech "
            f"({l['voice']}), post-processed by Team 3M. Not a real person's voice.")
    tmp = os.path.join(d, '.tmp.mp3')
    subprocess.run(['ffmpeg', '-v', 'error', '-y', '-i', os.path.join(d, f), '-c', 'copy', '-map_metadata', '-1',
        '-metadata', f'title={who}: {l["text"]}', '-metadata', 'artist=AI voice (Microsoft Azure neural TTS)',
        '-metadata', 'album=The Last Footprint · NASA Space Apps 2026 · Team 3M', '-metadata', f'comment={note}',
        '-metadata', f'language={"ara" if l["lang"] == "ar" else "eng"}', '-id3v2_version', '3', tmp], check=True)
    os.replace(tmp, os.path.join(d, f))
print('tagged', len([f for f in os.listdir(d) if f.endswith('.mp3')]))
